  const names = (arg('--names', '') || '').split(',').map((s) => s.trim()).filter(Boolean);
  const refresh = process.argv.includes('--refresh');
  const out = await mirror.statusFor(eco, names, refresh);
  console.log(JSON.stringify(out.results));
